  return new Promise((resolve, reject) => {
    setTimeout(() => {
      rainCounter++;
      if (rainCounter % 2 === 0) {
        reject(new Error("Rain API failed"));
      } else {
        resolve({
          Seattle: 13 + day,
          "San Mateo": 25 + day,
          Austin: 8 + day,
        });
      }
    }, 3000 * Math.random());
  });
}

